/** Identifiers are UUID strings generated by the database in production. */
export type UUID = string;

/** Roles included in the first release. Platform administration is internal-only for now. */
export type AppRole = "trainer" | "student";

export type TrainingGoal =
  | "hypertrophy"
  | "strength"
  | "conditioning"
  | "weight-loss"
  | "mobility";

export type ExerciseDifficulty = "beginner" | "intermediate" | "advanced";

export interface ExerciseSummary {
  id: UUID;
  name: string;
  muscleGroups: string[];
  equipment: string[];
  difficulty: ExerciseDifficulty;
}

export interface SetPrescription {
  setNumber: number;
  reps: string;
  targetLoadKg?: number;
  restSeconds: number;
  note?: string;
}

export interface WorkoutExercisePrescription {
  exercise: ExerciseSummary;
  order: number;
  sets: SetPrescription[];
  coachNote?: string;
}

export interface WorkoutSummary {
  id: UUID;
  trainerId: UUID;
  name: string;
  goal?: TrainingGoal;
  exercises: WorkoutExercisePrescription[];
}
